// Timed recognition round. Clock injection keeps expiry, pauses and feedback testable.
export function createSprint({ids,duration=60000,finite=false,random=Math.random,now=()=>performance.now(),onChange=()=>{},onAnswer=()=>{}}){
 let phase='idle',remaining=duration,countdown=3000,feedback=0,last=now(),paused=false,correct=0,attempted=0,streak=0,longest=0,points=0,order=[],cursor=0,target=null,result=null;
 function next(){if(cursor>=order.length){const previous=target;order=[...ids];for(let i=order.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}if(order.length>1&&order[0]===previous)[order[0],order[1]]=[order[1],order[0]];cursor=0;}target=order[cursor++];phase='playing';result=null;}
 function snapshot(){return {phase,remaining,countdown,paused,correct,attempted,streak,longest,points,target,result,duration,elapsedMs:duration-remaining,completed:finite&&attempted===ids.length};}
 function tick(){const t=now(),delta=Math.max(0,t-last);last=t;if(paused)return snapshot();const before=phase;if(phase==='countdown'){countdown=Math.max(0,countdown-delta);if(!countdown)next();}else if(phase==='playing'||phase==='feedback'){remaining=Math.max(0,remaining-delta);if(!remaining)phase='finished';else if(phase==='feedback'){feedback-=delta;if(feedback<=0)next();}}if(phase!==before)onChange(snapshot());return snapshot();}
 return {snapshot,tick,start(){if(!ids.length)return false;phase='countdown';remaining=duration;countdown=3000;paused=false;correct=attempted=streak=longest=points=cursor=0;order=[];target=null;result=null;last=now();onChange(snapshot());return true;},pause(){tick();paused=true;onChange(snapshot());},resume(){paused=false;last=now();onChange(snapshot());},answer(choice){tick();if(paused||phase!=='playing')return false;const right=choice===target;attempted++;correct+=Number(right);streak=right?streak+1:0;longest=Math.max(longest,streak);const earned=right?100+Math.min(100,(streak-1)*10):0;points+=earned;result={target,choice,correct:right,earned};phase=finite&&attempted===ids.length?'finished':'feedback';feedback=right?650:1100;onAnswer(result);onChange(snapshot());return true;}};
}
export function sprintBestKey(ids){return 'statequest.sprintBest.v1.'+[...ids].sort().join('-');}
export function readSprintBest(storage,ids){try{const n=JSON.parse(storage.getItem(sprintBestKey(ids)));return Number.isSafeInteger(n)&&n>=0?n:0;}catch{return 0;}}
export function saveSprintBest(storage,ids,count){const best=Math.max(readSprintBest(storage,ids),count);try{storage.setItem(sprintBestKey(ids),JSON.stringify(best));}catch{}return best;}
